<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { PhArrowRight, PhCheck, PhPlus, PhShoppingCart, PhTrash, PhX } from '@phosphor-icons/vue'
import { createCartItem, deleteCartItem, listCartItems, transferCartItem, updateCartItem } from '../utils/api'
const router = useRouter(); const items = ref([]); const loading = ref(true); const saving = ref(false); const selectedIds = ref([]); const editingId = ref(null); const showForm = ref(false); const toast = ref('')
const form = reactive({ name: '', category: '', price: '', specsText: '', image: '', note: '' })
const placeholderImage = `${import.meta.env.BASE_URL}images/placeholder-item.png`
const page = ref(1); const pageSize = 10
const pageCount = computed(() => Math.max(1, Math.ceil(items.value.length / pageSize)))
const visibleItems = computed(() => items.value.slice((page.value - 1) * pageSize, page.value * pageSize))
function goPage(next) { page.value = Math.min(pageCount.value, Math.max(1, next)) }
function notify(message) { toast.value = message; window.setTimeout(() => { toast.value = '' }, 2600) }
function specsFromText(text) { return Object.fromEntries(text.split('\n').map((line) => line.split(/[:：]/)).filter(([k, v]) => k?.trim() && v?.trim()).map(([k, ...v]) => [k.trim(), v.join(':').trim()])) }
function specsText(specs) { return Object.entries(specs || {}).map(([k, v]) => `${k}: ${v}`).join('\n') }
function validImageUrl(value) { if (!value) return true; try { const url = new URL(value); return url.protocol === 'http:' || url.protocol === 'https:' } catch { return false } }
function imageFallback(event) { event.target.src = placeholderImage }
function imageUrlIsValid(value) { if (!value) return true; try { const url = new URL(value); return url.protocol === 'http:' || url.protocol === 'https:' } catch { return false } }
function resetForm() { editingId.value = null; Object.assign(form, { name: '', category: '', price: '', specsText: '', image: '', note: '' }); showForm.value = true }
function closeForm() { if (!saving.value) showForm.value = false }
function edit(item) { editingId.value = item.id; Object.assign(form, { name: item.name, category: item.category || '', price: item.price ?? '', specsText: specsText(item.specs), image: item.image || '', note: item.note || '' }); showForm.value = true }
async function refresh() { loading.value = true; try { items.value = await listCartItems(); page.value = Math.min(page.value, Math.max(1, Math.ceil(items.value.length / pageSize))); selectedIds.value = selectedIds.value.filter((id) => items.value.some((item) => item.id === id)) } catch (error) { notify(error.message || '购物车读取失败') } finally { loading.value = false } }
async function save() { if (!form.name.trim() || saving.value) return; if (form.image.trim() && !validImageUrl(form.image.trim())) { notify('图片地址必须是 http:// 或 https:// 链接'); return } saving.value = true; const payload = { name: form.name.trim(), category: form.category.trim() || '其他', price: form.price === '' ? null : Number(form.price), specs: specsFromText(form.specsText), image: form.image.trim() || null, note: form.note.trim() || null }; try { if (editingId.value) await updateCartItem(editingId.value, payload); else await createCartItem(payload); showForm.value = false; editingId.value = null; await refresh(); notify('已保存') } catch (error) { notify(error.message || '保存失败') } finally { saving.value = false } }
async function remove(item) { try { await deleteCartItem(item.id); await refresh(); notify('已移除') } catch (error) { notify(error.message || '删除失败') } }
async function purchase(item) { try { await transferCartItem(item.id, { price: item.price, platform: null, purchased_at: new Date().toISOString(), note: item.note }); await refresh(); notify('已移入物品库') } catch (error) { notify(error.message || '移入失败') } }
function consultSelected() { if (selectedIds.value.length) router.push({ path: '/chat', query: { items: selectedIds.value.join(',') } }) }
onMounted(refresh)
</script>
<template>
  <div class="min-h-[calc(100dvh-4.5rem)] bg-zinc-50 dark:bg-zinc-950"><div class="mx-auto max-w-6xl px-5 pb-20 pt-9 sm:px-8 sm:pt-12">
    <div class="flex flex-wrap items-end justify-between gap-5 border-b border-zinc-200 pb-7 dark:border-zinc-800"><div><p class="text-xs font-semibold uppercase tracking-[0.16em] text-blue-600">Cart</p><h1 class="mt-2 text-2xl font-semibold text-zinc-950 dark:text-white">购物车</h1><p class="mt-2 text-sm text-zinc-500">保存待购买的商品参数，确认购买后可移入物品库。</p></div><button type="button" class="inline-flex h-10 items-center gap-2 rounded-lg bg-accent px-3.5 text-sm font-medium text-white" @click="resetForm"><PhPlus :size="17" />新增商品</button></div>
    <div class="mt-7 grid gap-5 lg:grid-cols-[minmax(0,1fr)_340px]"><section><div class="mb-3 flex items-center justify-between"><h2 class="text-sm font-semibold">待购买商品 <span class="ml-1 text-zinc-400">{{ items.length }}</span></h2><button type="button" :disabled="!selectedIds.length" class="inline-flex items-center gap-1 text-sm text-accent disabled:opacity-40" @click="consultSelected">带进咨询 <PhArrowRight :size="16" /></button></div><div v-if="loading" class="rounded-xl border bg-white px-6 py-16 text-center text-sm text-zinc-500">正在读取…</div><div v-else-if="!items.length" class="rounded-xl border border-dashed bg-white px-6 py-16 text-center dark:bg-zinc-900"><PhShoppingCart :size="30" class="mx-auto text-zinc-400" /><p class="mt-3 text-sm text-zinc-500">购物车还是空的</p></div><div v-else class="space-y-3"><article v-for="item in items" :key="item.id" class="flex gap-3 rounded-xl border border-zinc-200 bg-white p-4 dark:border-zinc-800 dark:bg-zinc-900"><input v-model="selectedIds" :value="item.id" type="checkbox" class="mt-1 h-4 w-4 accent-blue-600" /><img :src="item.image || placeholderImage" :alt="item.name" class="h-16 w-16 shrink-0 rounded-lg object-cover" @error="imageFallback" /><div class="min-w-0 flex-1"><div class="flex items-start justify-between gap-3"><div><p class="text-xs text-zinc-500">{{ item.category }}</p><h3 class="mt-1 font-semibold text-zinc-900 dark:text-white">{{ item.name }}</h3></div><span class="text-sm font-semibold">{{ item.price == null ? '—' : `${item.price} 元` }}</span></div><div v-if="Object.keys(item.specs || {}).length" class="mt-3 flex flex-wrap gap-1.5"><span v-for="(value, key) in item.specs" :key="key" class="rounded-md bg-zinc-100 px-2 py-1 text-xs text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300">{{ key }} {{ value }}</span></div><p v-if="item.note" class="mt-2 text-xs text-zinc-500">{{ item.note }}</p><div class="mt-3 flex gap-3 text-xs"><button type="button" class="text-accent" @click="edit(item)">编辑</button><button type="button" class="text-emerald-700 dark:text-emerald-300" @click="purchase(item)">已购买，移入物品库</button><button type="button" class="text-red-600" @click="remove(item)"><PhTrash :size="14" class="inline" /> 删除</button></div></div></article></div></section>
      <div v-if="showForm" class="fixed inset-0 z-50 flex items-center justify-center bg-zinc-950/50 px-4" role="dialog" aria-modal="true" @click.self="closeForm" @keydown.esc="closeForm"><div class="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-xl border border-zinc-200 bg-white p-5 shadow-xl dark:border-zinc-800 dark:bg-zinc-900"><div class="flex items-center justify-between"><h2 class="font-semibold">{{ editingId ? '编辑商品' : '新增商品' }}</h2><button type="button" aria-label="关闭" title="关闭" @click="closeForm"><PhX :size="17" /></button></div><form class="mt-5 space-y-3" @submit.prevent="save"><input v-model="form.name" required maxlength="256" placeholder="商品名称" class="h-10 w-full rounded-lg border px-3 text-sm dark:border-zinc-700 dark:bg-zinc-950" /><input v-model="form.category" maxlength="64" placeholder="分类" class="h-10 w-full rounded-lg border px-3 text-sm dark:border-zinc-700 dark:bg-zinc-950" /><input v-model="form.price" type="number" min="0" step="0.01" placeholder="价格（可选）" class="h-10 w-full rounded-lg border px-3 text-sm dark:border-zinc-700 dark:bg-zinc-950" /><textarea v-model="form.specsText" rows="4" placeholder="规格，每行一条：颜色: 黑色" class="w-full rounded-lg border px-3 py-2 text-sm dark:border-zinc-700 dark:bg-zinc-950" /><div class="flex items-center gap-3 rounded-lg border border-dashed border-zinc-300 p-2 dark:border-zinc-700"><img :src="form.image || placeholderImage" alt="图片预览" class="h-14 w-14 rounded-md object-cover" @error="imageFallback" /><input v-model="form.image" type="url" pattern="https?://.*" maxlength="512" placeholder="图片链接（可选）" title="请输入 http:// 或 https:// 图片地址" class="h-10 w-full rounded-lg border px-3 text-sm dark:border-zinc-700 dark:bg-zinc-950" /></div><textarea v-model="form.note" rows="2" maxlength="512" placeholder="备注" class="w-full rounded-lg border px-3 py-2 text-sm dark:border-zinc-700 dark:bg-zinc-950" /><button type="submit" :disabled="saving" class="inline-flex h-10 w-full items-center justify-center gap-2 rounded-lg bg-accent text-sm font-medium text-white disabled:opacity-50"><PhCheck :size="16" />{{ saving ? '保存中…' : '保存' }}</button></form></div></div></div>
    <p v-if="toast" class="fixed bottom-6 left-1/2 z-50 -translate-x-1/2 rounded-lg bg-zinc-900 px-4 py-2 text-sm text-white" role="status">{{ toast }}</p>
  </div></div>
</template>
